import{_ as n,C as a,o as i,c as o,E as t,a2 as c}from"./chunks/framework.VWKgVqrc.js";const v=JSON.parse('{"title":"Before calling a product passed, ask which checks entered the denominator","description":"","frontmatter":{"title":"Before calling a product passed, ask which checks entered the denominator","date":"2026-11-07","column":"open-source-engineering","category":"daily","article_type":"engineering-insight","edition":"research-center","research_question":"评测中的成品通过是否意味着所有计划都已有成绩？它与运行停止、历史里程碑通过有何区别？","research_question_en":"Does a scored product pass imply every planned check has a grade, and how does it differ from runtime stopping and historical milestone success?","summary":"A passed plan plus an ungraded plan can still yield a product pass; delivery evidence needs coverage and omission records.","sources":"https://arxiv.org/html/2611.05620v1","pageClass":"runtime-v6-article","item_id":"SIG-20261107-005","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-07-sig-20261107-005-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/engineering/2026-11-07-sig-20261107-005.md","filePath":"en/engineering/2026-11-07-sig-20261107-005.md","lastUpdated":null}'),l={name:"en/engineering/2026-11-07-sig-20261107-005.md"};function d(p,e,h,u,m,f){const r=a("ArticleCover"),s=a("ArticleTableScroll");return i(),o("div",null,[t(r,{image:"/assets/covers/daily-2026-11-07-sig-20261107-005-cover.png",kicker:"Research",title:"Before calling a product passed, ask which checks entered the denominator",summary:"A passed plan plus an ungraded plan can still yield a product pass; delivery evidence needs coverage and omission records.",version:"2026-11-07",languageHref:"/zh/engineering/2026-11-07-sig-20261107-005",languageLabel:"中文"}),t(s,{language:"en"}),e[0]||(e[0]=c('<h1 id="before-calling-a-product-passed-ask-which-checks-entered-the-denominator" tabindex="-1">Before calling a product passed, ask which checks entered the denominator <a class="header-anchor" href="#before-calling-a-product-passed-ask-which-checks-entered-the-denominator" aria-label="Permalink to &quot;Before calling a product passed, ask which checks entered the denominator&quot;">​</a></h1><p>Can a product pass when one check passes and another has no finished grade? The same-day synthetic-file probe returned yes in the pinned scorer, while retaining the missing plan in an audit field. This corrects no measured leaderboard. It demonstrates why a pass must be read alongside its scope of checks.</p><p>For software-agent delivery, a stopped run, success over included checks and completion of every required check are different propositions. A lone pass marker prevents the recipient from telling which evidence is actually available.</p><h2 id="one-pass-record-can-represent-two-coverage-levels" tabindex="-1">One pass record can represent two coverage levels <a class="header-anchor" href="#one-pass-record-can-represent-two-coverage-levels" aria-label="Permalink to &quot;One pass record can represent two coverage levels&quot;">​</a></h2><p>ViBench&#39;s public scorer uses a strict majority of full-point grades to pass a plan. A plan with no finished grade enters the missing-grade field and is omitted from both aggregate scores. Failed seeding with no grade instead counts as zero. A build can pass when its included plans have no failures. <a href="https://raw.githubusercontent.com/ViBench/vibench-public/main/harbor-adapter/src/vibench/score.py" target="_blank" rel="noreferrer">Official scoring source</a></p><p>The internal experiment supplies synthetic on-disk files to the content-pinned scorer. It runs neither a web product nor browser grading. One passing plan and one ungraded plan yield product pass=true, one included plan and a retained missing-plan entry. Two passing plans also yield a pass, now with two included plans. The same boolean therefore does not imply the same coverage completeness.</p><table tabindex="0"><thead><tr><th>Synthetic case</th><th>Internal experimental output</th><th>Interpretation boundary</th></tr></thead><tbody><tr><td>One passed, one ungraded</td><td>Product passes; one included; omission retained</td><td>Success over included checks</td></tr><tr><td>Both pass</td><td>Product passes; two included</td><td>Both checks have passing grades</td></tr><tr><td>Second plan has failed seeding</td><td>Product fails; plan pass rate is one half</td><td>Failed seeding is not ordinary absence of a grade</td></tr><tr><td>Second plan has a tied vote</td><td>Product fails</td><td>Strict majority is not at least half</td></tr><tr><td>Both ungraded</td><td>Null result</td><td>No usable denominator, rather than zero</td></tr><tr><td>Both have too few grades</td><td>Null; exclusion reasons retained</td><td>Grade-count requirements are separate from values</td></tr></tbody></table><p>Every result cell is internal evidence. The <a href="/joinwell52/assets/evidence/2026-11-07-sig-20261107-005/denominator-experiment.json">scorer-case record</a> retains inputs and actual outputs. The experiment preserves the original scoring logic while using doubles for package-level plan discovery, provenance and unused cost collection. It performs no real build, closed-model grading or held-out-product test. These files establish neither a vulnerability in the full benchmark nor a correction to paper scores.</p><h2 id="historical-all-step-success-and-final-product-success-ask-different-questions" tabindex="-1">Historical all-step success and final-product success ask different questions <a class="header-anchor" href="#historical-all-step-success-and-final-product-success-ask-different-questions" aria-label="Permalink to &quot;Historical all-step success and final-product success ask different questions&quot;">​</a></h2><p>Multi-step SWE requires full credit at every historical milestone; a final repair cannot erase an earlier failed milestone. The source reports 56.8% step pass for the strongest model-harness pair but 18.5% whole-sequence solve rate, with a confidence interval of 11.6–25.7% for the latter. They measure different events rather than contradicting one another. <a href="https://arxiv.org/html/2611.07166v1" target="_blank" rel="noreferrer">Paper, sections 3–5</a></p><p>ViBench evaluates the final artifact. Its authors report 96.9% plan pass and 64.7% full-product pass for one model, and 98.0% versus 60.3% for another. A late repair can affect final-product checks, while an all-history contract retains earlier failure. Different plan counts, acceptance times and missing-grade treatment prevent direct ranking of benchmark difficulty or system quality from those percentages. <a href="https://arxiv.org/html/2611.05620v1" target="_blank" rel="noreferrer">Paper, sections 2–4</a></p><p>A representative multi-step task manifest uses mean step reward as its trial reward, again distinct from the paper&#39;s all-step solve rate. Its verifier wrapper checks privilege isolation, rebuilds sources and checks test integrity. Only one representative wrapper was inspected; its called helper and scoring implementations were not fully audited. <a href="https://raw.githubusercontent.com/Klavis-AI/Multi-step-SWE/main/tasks/lua-vm-version-chain/task.toml" target="_blank" rel="noreferrer">Official task manifest</a>, <a href="https://raw.githubusercontent.com/Klavis-AI/Multi-step-SWE/main/tasks/lua-vm-version-chain/steps/01-lua-5-1/tests/test.sh" target="_blank" rel="noreferrer">verifier wrapper</a></p><h2 id="a-stopped-system-has-not-automatically-earned-external-acceptance" tabindex="-1">A stopped system has not automatically earned external acceptance <a class="header-anchor" href="#a-stopped-system-has-not-automatically-earned-external-acceptance" aria-label="Permalink to &quot;A stopped system has not automatically earned external acceptance&quot;">​</a></h2><p>The inspected MetaGPT team-run method stops on idle or exhausted rounds, archives and returns history. The base environment is idle when every role is idle. These describe operational state, not external acceptance of an artifact&#39;s correctness. <a href="https://raw.githubusercontent.com/FoundationAgents/MetaGPT/main/metagpt/team.py" target="_blank" rel="noreferrer">Team source</a>, <a href="https://raw.githubusercontent.com/FoundationAgents/MetaGPT/main/metagpt/environment/base_env.py" target="_blank" rel="noreferrer">base environment</a></p><p>This does not establish that the whole framework lacks validators. Other paths may validate, and the default extended environment&#39;s override was not inspected here. The supported comparison concerns three inspected predicates: historical process contracts, final-artifact acceptance and runtime stopping. A completion marker becomes interpretable only after its question is specified.</p><p>Our engineering interpretation is to bind the acceptance contract, actual artifact and scorer version, retaining separate records for termination, included checks, required-check completion, failures and exclusions. If the contract requires a result for every mandatory check, validate coverage completeness separately. This recommendation has no deployment-effect experiment behind it and does not imply oracle infallibility.</p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><p>Model scores are source-reported claims. Public scorer and stopping methods are inspected implementation facts. Six synthetic-file cases are internal experimental evidence. A separate acceptance process is different from an independent third-party reproduction: this research reproduces neither full benchmark and executes no real product tests. Publication, citation and visible source cannot substitute for result validation.</p><p>The main sources are the <a href="https://arxiv.org/html/2611.07166v1" target="_blank" rel="noreferrer">Multi-step SWE preprint, arXiv 2611.07166, version 1</a>, the <a href="https://arxiv.org/html/2611.05620v1" target="_blank" rel="noreferrer">ViBench preprint, arXiv 2611.05620, version 1</a> and the adjacent official-code links above. Implementation observations are limited to content-pinned same-run snapshots, not confirmed paper-release commits. Nine ViBench products are held out and eight are public; a public-scorer probe is not full reproduction coverage.</p><h2 id="when-do-omissions-alter-an-actual-conclusion" tabindex="-1">When do omissions alter an actual conclusion? <a class="header-anchor" href="#when-do-omissions-alter-an-actual-conclusion" aria-label="Permalink to &quot;When do omissions alter an actual conclusion?&quot;">​</a></h2><p>This research measures neither why grades are missing, their incidence in real builds nor their effect on model rankings. The paper says no affected independent build it examined changed first-pass success because of the relevant omissions; we did not recompute that claim. Required-plan inventories, completion records, exclusion reasons and a fixed scorer version are needed per build to establish how much delivery responsibility a pass actually covers.</p>',21))])}const b=n(l,[["render",d]]);export{v as __pageData,b as default};
